// Simula a instrumentação da comporta da PCH Ivan Botelho III
const NA = 286.2 + (Math.random() - 0.5) * 0.06;      // nível do reservatório (m)
const cotaSensor = 273.0;                              // cota do piezômetro (m)
const teorica = 1000 * 9.81 * (NA - cotaSensor) / 1000; // kPa
const anomalia = flow.get('anomalia') || false;
msg.payload = {
  dispositivo_id: 'ivan-botelho-3',
  timestamp: new Date().toISOString(),
  seq: (flow.get('seq') || 0) + 1,
  leituras: {
    abertura_pct: +(15 + Math.random() * 4).toFixed(1),
    nivel_reservatorio_m: +NA.toFixed(2),
    pressao_kpa: +(teorica * (anomalia ? 1.25 : 1 + (Math.random() - 0.5) * 0.03)).toFixed(1),
    carga_pct: +(60 + Math.random() * 6).toFixed(1),
    vibracao_mm_s: +((anomalia ? 8 : 2) + Math.random()).toFixed(2)
  }
};
flow.set('seq', msg.payload.seq);
msg.teorica = teorica;
return msg;

// Regra de borda (edge): SE desvio de pressão >= 15% ENTÃO marca prioridade alta
const p = msg.payload.leituras.pressao_kpa;
const desvio = Math.abs(p - msg.teorica) / msg.teorica * 100;
msg.headers = { 'Content-Type': 'application/json', 'X-Prioridade': desvio >= 15 ? 'alta' : 'normal' };
if (desvio >= 15) node.warn(`Desvio de pressão ${desvio.toFixed(1)}%: enviando com prioridade alta`);
// Store-and-forward: envia junto o que ficou na fila durante a queda de conexão
const fila = flow.get('fila') || [];
msg.payload = fila.concat([msg.payload]);
flow.set('pendente', msg.payload);
return msg;

// 2xx: limpa a fila. Erro de rede/5xx: guarda para retransmitir (até 500 leituras)
if (msg.statusCode >= 200 && msg.statusCode < 300) { flow.set('fila', []); }
else { const p = flow.get('pendente') || []; flow.set('fila', p.slice(-500)); node.warn('Falha no envio; ' + p.length + ' leitura(s) na fila'); }
return msg;
